"""Create nominal coordinate SVG viewer; no source artwork/map mutation."""
from pathlib import Path
import hashlib,json,math,html
BASE=Path(__file__).resolve().parents[1];OUT=Path(__file__).resolve().parent
plan=json.loads((BASE/'geometry/twentyfive-regions.json').read_text());review=json.loads((BASE/'review-manifest.json').read_text())
q=math.sqrt(.5);s=math.sin(math.radians(62.5))
def project(p):return [(p[0]-p[1])*q,(p[0]+p[1])*q*s]
placed=[];images=[];clips=[];edges=[];labels=[];ground=[]
for it in review['items']:
 region=next(r for r in plan['regions'] if r['id']==it['regionId']);path=BASE/it['file'];guide=json.loads((path.parent/'guide-record.json').read_text());sha=hashlib.sha256(path.read_bytes()).hexdigest();assert sha==it['sha256']
 ratio=it['nativeSize'][0]/guide['size'][0];ppm=guide['pixelsPerProjectedMetre']*ratio
 left=guide['projectedMin'][0]-guide['canvasOffset'][0]/guide['pixelsPerProjectedMetre'];top=guide['projectedMin'][1]-guide['canvasOffset'][1]/guide['pixelsPerProjectedMetre'];width,height=[v/ppm for v in it['nativeSize']];core=[project(p) for p in region['corePolygonMetres']];ground+=core
 pts=' '.join(f'{p[0]:.4f},{p[1]:.4f}' for p in core);id=it['regionId'];href='../'+it['file'];clips.append(f'<clipPath id="clip-{id}"><polygon points="{pts}"/></clipPath>');images.append(f'<g class="tile" data-clip="url(#clip-{id})" clip-path="url(#clip-{id})"><image href="{html.escape(href)}" x="{left}" y="{top}" width="{width}" height="{height}" preserveAspectRatio="none"/></g>');edges.append(f'<polygon points="{pts}" fill="none" stroke="#f08031" stroke-width="2" vector-effect="non-scaling-stroke"/>');c=project([(region['coreBoundsMetres']['minX']+region['coreBoundsMetres']['maxX'])/2,(region['coreBoundsMetres']['minY']+region['coreBoundsMetres']['maxY'])/2]);labels.append(f'<text x="{c[0]}" y="{c[1]}" text-anchor="middle" font-size="45" fill="white" stroke="#153a47" stroke-width="5" paint-order="stroke">{it["label"]} {id}</text>');placed.append(dict(label=it['label'],id=id,file=it['file'],sha256=sha,nativePixelsPerProjectedMetre=ppm,imageBoundsProjected=[left,top,left+width,top+height],corePolygonProjected=core,registration='preview-only',placement='nominal-source-guide-transform;not-measured-image-registration'))
city=json.loads((BASE.parents[2]/'delivery-game/assets/resources/map-sample/city.json').read_text());nodes={str(n['id']):[n['x'],n['y']] for n in city['nodes']};roads=[]
for r in city['roads']:
 ps=[project(nodes[str(n)]) for n in r['nodes']];pts=' '.join(f'{p[0]:.3f},{p[1]:.3f}' for p in ps);roads.append(f'<polyline points="{pts}" fill="none" stroke="#ff00d4" stroke-opacity=".8" stroke-width="1.4" vector-effect="non-scaling-stroke"/>')
lo=[min(p[i] for p in ground)-150 for i in [0,1]];hi=[max(p[i] for p in ground)+150 for i in [0,1]];box=[lo[0],lo[1],hi[0]-lo[0],hi[1]-lo[1]]
body='''<!doctype html><html lang="zh"><meta charset="utf-8"><style>body{margin:0;font:14px var(--font-sans);color:var(--foreground)}nav{display:flex;gap:12px;flex-wrap:wrap;padding:10px 0}button{padding:6px 12px}svg{width:100%;height:680px;background:#dedbd5;touch-action:none;cursor:grab}p{color:var(--muted-foreground)}</style><p>25区名义坐标拼接诊断 · 非实测配准/最终地图。滚轮缩放，拖动平移。core裁切可能切楼树；关闭裁切可检查原图底色重叠。</p><nav><button onclick="reset()">全县</button><label><input type="checkbox" checked onchange="toggle('seams',this.checked)">分区接缝</label><label><input type="checkbox" checked onchange="toggle('labels',this.checked)">图号</label><label><input type="checkbox" onchange="toggle('roads',this.checked)">原路参考</label><label><input type="checkbox" checked onchange="clip(this.checked)">core归属裁切</label></nav>'''
body+=f'<svg id="map" viewBox="{" ".join(map(str,box))}"><defs>'+''.join(clips)+'</defs>'+''.join(images)+'<g id="seams">'+''.join(edges)+'</g><g id="roads" style="display:none">'+''.join(roads)+'</g><g id="labels">'+''.join(labels)+'</g></svg>'
body+='''<script>const svg=document.getElementById('map'),initial=BOX;let b=[...initial],last=null;function draw(){svg.setAttribute('viewBox',b.join(' '))}function reset(){b=[...initial];draw()}function toggle(id,on){document.getElementById(id).style.display=on?'':'none'}function clip(on){document.querySelectorAll('.tile').forEach(x=>on?x.setAttribute('clip-path',x.dataset.clip):x.removeAttribute('clip-path'))}svg.addEventListener('wheel',e=>{e.preventDefault();let r=svg.getBoundingClientRect(),u=(e.clientX-r.left)/r.width,v=(e.clientY-r.top)/r.height,k=e.deltaY>0?1.15:1/1.15;b=[b[0]+b[2]*u*(1-k),b[1]+b[3]*v*(1-k),b[2]*k,b[3]*k];draw()},{passive:false});svg.onpointerdown=e=>{svg.setPointerCapture(e.pointerId);last=[e.clientX,e.clientY]};svg.onpointerup=()=>last=null;svg.onpointermove=e=>{if(!last)return;let r=svg.getBoundingClientRect();b[0]-=(e.clientX-last[0])*b[2]/r.width;b[1]-=(e.clientY-last[1])*b[3]/r.height;last=[e.clientX,e.clientY];draw()};</script></html>'''.replace('BOX',json.dumps(box))
(OUT/'preview.html').write_text(body);(OUT/'placement-manifest.json').write_text(json.dumps(dict(status='preview-only',regions=placed,sourceRoadOverlay=True,sourceArtModified=False,limitations=['Nominal guide coordinate placement, actual generated road/ground projection not measured.','Opaque backgrounds/core clipping may create visible gaps or truncate silhouettes.','No routing enabled, no game testing, no highresolution claim.']),ensure_ascii=False,indent=2)+'\n');print(json.dumps({'regionsPlaced':len(placed),'sourceSHAValidated':True,'viewer':'assembly/preview.html','registration':'preview-only'}))
